  min-width: 0 !important;
  height: calc(var(--rrb-segmented-height) - 4px) !important;
  min-height: calc(var(--rrb-segmented-height) - 4px) !important;
  max-height: calc(var(--rrb-segmented-height) - 4px) !important;
